-- ── 1. The bounds, contract 2: the account envelope joins the family ───────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.fs_work_bounds()
RETURNS jsonb LANGUAGE sql STABLE SET search_path = pg_catalog, public AS $$
  SELECT jsonb_build_object(
    'contract', 'fs-work-bounds/2',
    'evidenceRowsPerBatch', 1000,
    'evidenceDocumentBytesPerBatch', 1048576,
    'evidenceRowsPerVersion', 3000,
    'reportDocumentBytes', 8388608,
    'versionsPerLineage', 1000,
    'commentsPerVersion', 500,
    'eventsPerComment', 200,
    'accountsReadPerComposition', 1000
  );
$$;
REVOKE ALL ON FUNCTION public.fs_work_bounds() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.fs_work_bounds() TO authenticated;

-- ── 2. Evidence batches: rows and bytes per batch ──────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.fs_bound_evidence_batch()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog, public AS $$
DECLARE
  v_b     jsonb := public.fs_work_bounds();
  v_rows  integer;
  v_bytes bigint;
BEGIN
  v_rows := CASE WHEN jsonb_typeof(NEW.batch_document -> 'rows') = 'array' THEN jsonb_array_length(NEW.batch_document -> 'rows') ELSE 0 END;
  IF v_rows > (v_b ->> 'evidenceRowsPerBatch')::integer THEN
    RAISE EXCEPTION 'EVIDENCE_ROWS_LIMIT: the % file has % data rows; at most % rows are accepted in one evidence file (split the file by period or account)',
      NEW.evidence_type, v_rows, v_b ->> 'evidenceRowsPerBatch' USING ERRCODE = '22023';
  END IF;
  v_bytes := octet_length(NEW.batch_document::text);
  IF v_bytes > (v_b ->> 'evidenceDocumentBytesPerBatch')::bigint THEN
    RAISE EXCEPTION 'EVIDENCE_DOCUMENT_SIZE_LIMIT: the % file is % bytes as evidence; at most % bytes are accepted in one evidence file',
      NEW.evidence_type, v_bytes, v_b ->> 'evidenceDocumentBytesPerBatch' USING ERRCODE = '22023';
  END IF;
  RETURN NEW;
END;
$$;

-- ── 2. What is counted ─────────────────────────────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.fs_account_capacity(p_company_id uuid, p_period_year integer)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  v_cur uuid;
  v_pri uuid;
  v_c integer := 0;
  v_p integer := 0;
  v_b integer := (public.fs_work_bounds() ->> 'accountsReadPerComposition')::integer;
BEGIN
  IF p_company_id IS NULL OR p_period_year IS NULL THEN RETURN jsonb_build_object('state', 'invalid_request'); END IF;
  IF NOT public.close_review_readable(p_company_id) THEN RETURN jsonb_build_object('state', 'unavailable'); END IF;
  SELECT c.id INTO v_cur FROM public.get_authoritative_certification(p_company_id, p_period_year) c;
  SELECT c.id INTO v_pri FROM public.get_authoritative_certification(p_company_id, p_period_year - 1) c;
  IF v_cur IS NOT NULL THEN SELECT count(DISTINCT a.account_key) INTO v_c FROM public._cr_certified_accounts(v_cur) a; END IF;
  IF v_pri IS NOT NULL THEN SELECT count(DISTINCT a.account_key) INTO v_p FROM public._cr_certified_accounts(v_pri) a; END IF;
  RETURN jsonb_build_object('state', 'measured', 'contract', 'fs-account-capacity/1', 'periodYear', p_period_year,
    'current', v_c, 'comparative', v_p, 'total', v_c + v_p, 'bound', v_b, 'within', (v_c + v_p) <= v_b);
END;
$$;
REVOKE ALL ON FUNCTION public.fs_account_capacity(uuid, integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.fs_account_capacity(uuid, integer) TO authenticated;

-- ── 3. The composition refuses first (notes and dependencies follow it) ────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.fs_statement_composition(p_company_id uuid, p_period_year integer)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  v_input jsonb;
  v_edition jsonb;
  v_cur jsonb;
  v_cmp jsonb;
  v_cmp_state text;
  v_lines jsonb;
  v_totals jsonb;
  v_accounts jsonb;
  v_blockers text[] := '{}';
  v_body jsonb;
  v_n integer;
BEGIN
  IF p_company_id IS NULL OR p_period_year IS NULL THEN RETURN jsonb_build_object('state', 'invalid_request'); END IF;
  IF NOT public.close_review_readable(p_company_id) THEN RETURN jsonb_build_object('state', 'unavailable'); END IF;
  -- [20261115100000] Account capacity, decided BEFORE the reporting input and the composition are computed: the number of
  -- certified accounts the composition would read (current + comparative periods) against fs_work_bounds().
  DECLARE
    v_cap jsonb := public.fs_account_capacity(p_company_id, p_period_year);
  BEGIN
    IF v_cap ->> 'state' = 'measured' AND NOT (v_cap ->> 'within')::boolean THEN
      RETURN jsonb_build_object('state', 'over_capacity', 'capacity', v_cap, 'periodYear', p_period_year,
        'reason', format('%s accounts across the current and comparative trial balances; this release supports %s', v_cap ->> 'total', v_cap ->> 'bound'));
    END IF;
  END;
  v_input := public.fs_reporting_input(p_company_id, p_period_year);
  IF v_input ->> 'state' IS DISTINCT FROM 'current' THEN
    RETURN jsonb_build_object('state', coalesce(v_input ->> 'state', 'unavailable'), 'periodYear', p_period_year);
  END IF;
  v_cur := v_input -> 'current';
  v_edition := public._fs_smes_edition_decide((SELECT c.reporting_framework FROM public.companies c WHERE c.id = p_company_id),
                                              (v_cur ->> 'reportingStart')::date, public._fs_smes_elected(p_company_id, p_period_year));
  IF v_edition ->> 'state' <> 'resolved' THEN
    RETURN jsonb_build_object('state', 'edition_unresolved', 'reason', v_edition ->> 'reason', 'periodYear', p_period_year, 'inputSha256', v_input ->> 'inputSha256');
  END IF;
  v_cmp := v_input -> 'comparative';
  v_cmp_state := CASE WHEN v_cmp ->> 'state' = 'available' AND (v_cmp ->> 'currency' IS DISTINCT FROM v_cur ->> 'currency' OR v_cmp ->> 'exponent' IS DISTINCT FROM v_cur ->> 'exponent')
                      THEN 'different_currency' ELSE v_cmp ->> 'state' END;

  CREATE TEMP TABLE IF NOT EXISTS pg_temp.fs_comp_rows (role text, cert text, k text, code text, name text, classification text, section text,
    debit_net numeric, cert_debit_net numeric, adjustments jsonb, line_id text, statement text, label text, requirement_id text, sort_order integer,
    position text, natures text[], asg_id uuid, asg_seq bigint, status text, amount numeric, cert_amount numeric, kind text, ref uuid) ON COMMIT DROP;
  TRUNCATE pg_temp.fs_comp_rows;
  INSERT INTO pg_temp.fs_comp_rows
  WITH br AS (
    -- Account bridges: a prior-year account presented through the current account it became (latest event wins; a
    -- withdrawal leaves current_account_key NULL, i.e. no bridge).
    SELECT DISTINCT ON (b.prior_account_key) b.prior_account_key, b.current_account_key, b.id FROM public.fs_comparative_bridges b
     WHERE b.company_id = p_company_id AND b.period_year = p_period_year ORDER BY b.prior_account_key, b.seq DESC),
  asg AS (
    SELECT DISTINCT ON (a.account_key) a.account_key, a.line_id, a.id, a.seq FROM public.fs_presentation_assignments a
     WHERE a.company_id = p_company_id AND a.pack_family = 'ifrs-for-smes' ORDER BY a.account_key, a.seq DESC),
  acc AS (
    SELECT 'current'::text AS role, v_cur ->> 'certificationId' AS cert, x AS a FROM jsonb_array_elements(v_cur -> 'accounts') x
    UNION ALL
    SELECT 'comparative', v_cmp ->> 'certificationId', x FROM jsonb_array_elements(CASE WHEN v_cmp_state = 'available' THEN v_cmp -> 'accounts' ELSE '[]'::jsonb END) x),
  base AS (
    SELECT acc.role, acc.cert, acc.a ->> 'accountKey' AS k, acc.a ->> 'accountCode' AS code, acc.a ->> 'accountName' AS name,
           acc.a ->> 'classification' AS classification, public._fs_section(acc.a ->> 'classification') AS section,
           (acc.a ->> 'debitMinor')::numeric - (acc.a ->> 'creditMinor')::numeric AS debit_net,
           (acc.a ->> 'certifiedDebitMinor')::numeric - (acc.a ->> 'certifiedCreditMinor')::numeric AS cert_debit_net,
           coalesce(acc.a -> 'adjustmentIds', '[]'::jsonb) AS adjustments,
           asg.line_id, l.statement, l.label, l.requirement_id, l.sort_order, l.position, l.natures, asg.id AS asg_id, asg.seq AS asg_seq,
           CASE WHEN acc.role = 'comparative' AND br.current_account_key IS NOT NULL THEN br.id END AS bridge_id
      FROM acc
      LEFT JOIN br ON acc.role = 'comparative' AND br.prior_account_key = acc.a ->> 'accountKey'
      LEFT JOIN asg ON asg.account_key = CASE WHEN acc.role = 'comparative' THEN coalesce(br.current_account_key, acc.a ->> 'accountKey') ELSE acc.a ->> 'accountKey' END
      LEFT JOIN public.fs_presentation_lines l ON l.pack_family = 'ifrs-for-smes' AND l.line_id = asg.line_id)
  SELECT b.role, b.cert, b.k, b.code, b.name, b.classification, b.section, b.debit_net, b.cert_debit_net, b.adjustments, b.line_id, b.statement, b.label,
         b.requirement_id, b.sort_order, b.position, b.natures, b.asg_id, b.asg_seq,
         public._fs_presentation_status(b.section, b.line_id, b.statement, b.natures, b.position),
         public._fs_line_amount(b.statement, b.section, b.line_id, b.debit_net), public._fs_line_amount(b.statement, b.section, b.line_id, b.cert_debit_net),
         'account', b.bridge_id
    FROM base b;

  -- Approved restatements of the comparative: each line delta is a presented comparative row of its own, so lines and
  -- totals include it and its lineage names it. Only when the comparative is available in the same currency.
  IF v_cmp_state = 'available' THEN
    INSERT INTO pg_temp.fs_comp_rows
    SELECT 'comparative', v_cmp ->> 'certificationId', 'restatement:' || r.id::text, NULL, r.reason, NULL, x ->> 'section', NULL, NULL, '[]'::jsonb,
           x ->> 'lineId', l.statement, l.label, l.requirement_id, l.sort_order, l.position, l.natures, NULL, NULL,
           'presented', (x ->> 'deltaMinor')::numeric, 0, 'restatement', r.id
      FROM public._fs_approved_restatements(p_company_id, p_period_year) r
      CROSS JOIN LATERAL jsonb_array_elements(r.lines) x
      JOIN public.fs_presentation_lines l ON l.pack_family = 'ifrs-for-smes' AND l.line_id = x ->> 'lineId';
  END IF;

  -- Lines: one per (statement, section, line) for the statement of financial position; one per line for the statement of
  -- comprehensive income. A period's amount is the exact sum of its presented accounts (an account absent from a complete
  -- certified trial balance has no balance); the comparative is null unless the prior year is available in the same
  -- currency.
  WITH g AS (
    SELECT r.statement, CASE WHEN r.statement = 'SFP' THEN r.section ELSE 'sci' END AS grp, r.line_id, min(r.label) AS label, min(r.requirement_id) AS req, min(r.sort_order) AS sort,
           coalesce(sum(r.amount) FILTER (WHERE r.role = 'current'), 0) AS cur_amt, count(*) FILTER (WHERE r.role = 'current') AS cur_n,
           coalesce(sum(r.amount) FILTER (WHERE r.role = 'comparative'), 0) AS cmp_amt, count(*) FILTER (WHERE r.role = 'comparative' AND r.kind = 'account') AS cmp_n,
           coalesce(sum(r.amount) FILTER (WHERE r.role = 'comparative' AND r.kind = 'account'), 0) AS cmp_reported,
           count(*) FILTER (WHERE r.role = 'comparative' AND r.kind = 'restatement') AS cmp_restated,
           jsonb_agg(jsonb_build_object('period', r.role, 'accountKey', r.k, 'accountCode', r.code, 'accountName', r.name, 'certificationId', r.cert,
             'classification', r.classification, 'amountMinor', r.amount::text, 'certifiedAmountMinor', r.cert_amount::text, 'adjustmentIds', r.adjustments,
             'assignmentId', r.asg_id, 'assignmentSeq', r.asg_seq, 'kind', r.kind,
             'bridgeId', CASE WHEN r.kind = 'account' THEN r.ref END, 'restatementId', CASE WHEN r.kind = 'restatement' THEN r.ref END) ORDER BY r.role DESC, r.k) AS lineage
      FROM pg_temp.fs_comp_rows r WHERE r.status = 'presented' GROUP BY 1, 2, 3)
  SELECT coalesce(jsonb_agg(jsonb_build_object('statement', g.statement, 'section', g.grp, 'lineId', g.line_id, 'label', g.label, 'requirementId', g.req,
           'current', jsonb_build_object('amountMinor', g.cur_amt::text, 'accounts', g.cur_n),
           'comparative', CASE WHEN v_cmp_state = 'available' THEN jsonb_build_object('amountMinor', g.cmp_amt::text, 'accounts', g.cmp_n,
                            'asReportedMinor', g.cmp_reported::text, 'restated', g.cmp_restated > 0) END,
           'lineage', g.lineage)
         ORDER BY g.statement DESC, array_position(ARRAY['non_current_assets', 'current_assets', 'equity', 'non_current_liabilities', 'current_liabilities', 'sci'], g.grp), g.sort), '[]'::jsonb)
    INTO v_lines FROM g;

  -- Totals per period, only when every account of that period is presented.
  SELECT jsonb_object_agg(p.role, CASE WHEN p.not_presented > 0 THEN jsonb_build_object('state', 'incomplete', 'notPresented', p.not_presented)
    ELSE jsonb_build_object('state', 'complete',
      'nonCurrentAssetsMinor', p.nca::text, 'currentAssetsMinor', p.ca::text, 'totalAssetsMinor', (p.nca + p.ca)::text,
      'currentLiabilitiesMinor', p.cl::text, 'nonCurrentLiabilitiesMinor', p.ncl::text, 'totalLiabilitiesMinor', (p.cl + p.ncl)::text,
      'equityAccountsMinor', p.eq::text, 'incomeMinor', p.inc::text, 'expensesExcludingTaxMinor', p.exp::text,
      'profitBeforeTaxMinor', (p.inc - p.exp)::text, 'taxExpenseMinor', p.tax::text, 'profitOrLossMinor', (p.inc - p.exp - p.tax)::text,
      'totalEquityMinor', (p.eq + p.inc - p.exp - p.tax)::text,
      'totalEquityAndLiabilitiesMinor', (p.cl + p.ncl + p.eq + p.inc - p.exp - p.tax)::text,
      'balanceDifferenceMinor', ((p.nca + p.ca) - (p.cl + p.ncl + p.eq + p.inc - p.exp - p.tax))::text) END)
    INTO v_totals
    FROM (SELECT r.role,
                 count(*) FILTER (WHERE r.status <> 'presented') AS not_presented,
                 coalesce(sum(r.amount) FILTER (WHERE r.status = 'presented' AND r.statement = 'SFP' AND r.section = 'non_current_assets'), 0) AS nca,
                 coalesce(sum(r.amount) FILTER (WHERE r.status = 'presented' AND r.statement = 'SFP' AND r.section = 'current_assets'), 0) AS ca,
                 coalesce(sum(r.amount) FILTER (WHERE r.status = 'presented' AND r.statement = 'SFP' AND r.section = 'current_liabilities'), 0) AS cl,
                 coalesce(sum(r.amount) FILTER (WHERE r.status = 'presented' AND r.statement = 'SFP' AND r.section = 'non_current_liabilities'), 0) AS ncl,
                 coalesce(sum(r.amount) FILTER (WHERE r.status = 'presented' AND r.statement = 'SFP' AND r.section = 'equity'), 0) AS eq,
                 coalesce(sum(r.amount) FILTER (WHERE r.status = 'presented' AND r.statement = 'SCI' AND r.line_id IN ('sci.revenue', 'sci.other_income', 'sci.share_of_associates')), 0) AS inc,
                 coalesce(sum(r.amount) FILTER (WHERE r.status = 'presented' AND r.statement = 'SCI' AND r.line_id NOT IN ('sci.revenue', 'sci.other_income', 'sci.share_of_associates', 'sci.tax_expense')), 0) AS exp,
                 coalesce(sum(r.amount) FILTER (WHERE r.status = 'presented' AND r.statement = 'SCI' AND r.line_id = 'sci.tax_expense'), 0) AS tax
            FROM pg_temp.fs_comp_rows r GROUP BY r.role) p;

  SELECT coalesce(jsonb_agg(jsonb_build_object('period', r.role, 'accountKey', r.k, 'accountCode', r.code, 'accountName', r.name,
           'classification', r.classification, 'status', r.status, 'lineId', r.line_id) ORDER BY r.role DESC, r.status, r.k), '[]'::jsonb)
    INTO v_accounts FROM pg_temp.fs_comp_rows r WHERE r.status <> 'presented';

  SELECT count(*) INTO v_n FROM pg_temp.fs_comp_rows r WHERE r.role = 'current' AND r.status = 'unassigned';
  IF v_n > 0 THEN v_blockers := v_blockers || ('PRESENTATION_UNASSIGNED:' || v_n); END IF;
  SELECT count(*) INTO v_n FROM pg_temp.fs_comp_rows r WHERE r.role = 'current' AND r.status = 'incompatible';
  IF v_n > 0 THEN v_blockers := v_blockers || ('PRESENTATION_INCOMPATIBLE:' || v_n); END IF;
  SELECT count(*) INTO v_n FROM pg_temp.fs_comp_rows r WHERE r.role = 'current' AND r.status = 'excluded';
  IF v_n > 0 THEN v_blockers := v_blockers || ('ACCOUNTS_NOT_PRESENTABLE:' || v_n); END IF;
  -- 5.11: one analysis of expenses — by function or by nature, never both.
  IF EXISTS (SELECT 1 FROM pg_temp.fs_comp_rows r WHERE r.role = 'current' AND r.status = 'presented' AND r.line_id IN ('sci.cost_of_sales', 'sci.operating_expenses_by_function'))
     AND EXISTS (SELECT 1 FROM pg_temp.fs_comp_rows r WHERE r.role = 'current' AND r.status = 'presented' AND r.line_id IN ('sci.employee_benefits_expense', 'sci.depreciation_and_amortisation', 'sci.other_expenses_by_nature')) THEN
    v_blockers := v_blockers || 'EXPENSE_ANALYSIS_MIXED'::text;
  END IF;
  IF v_totals -> 'current' ->> 'state' = 'complete' AND (v_totals -> 'current' ->> 'balanceDifferenceMinor')::numeric <> 0 THEN
    v_blockers := v_blockers || ('BALANCE_DIFFERENCE:' || (v_totals -> 'current' ->> 'balanceDifferenceMinor'));
  END IF;

  v_body := jsonb_build_object(
    'contract', 'fs-statement-composition/2',
    'pack', jsonb_build_object('family', 'ifrs-for-smes', 'linesVersion', '1.0.0', 'packId', v_edition ->> 'packId', 'earlyApplication', (v_edition ->> 'earlyApplication')::boolean),
    'inputSha256', v_input ->> 'inputSha256',
    'current', jsonb_build_object('periodYear', p_period_year, 'certificationId', v_cur ->> 'certificationId', 'currency', v_cur ->> 'currency',
                                  'exponent', (v_cur ->> 'exponent')::integer, 'reportingStart', v_cur ->> 'reportingStart', 'reportingEnd', v_cur ->> 'reportingEnd'),
    'comparative', jsonb_build_object('state', v_cmp_state, 'periodYear', (v_cmp ->> 'periodYear')::integer, 'certificationId', v_cmp ->> 'certificationId',
                                      'currency', v_cmp ->> 'currency',
                                      'bridgeIds', (SELECT coalesce(jsonb_agg(DISTINCT r.ref ORDER BY r.ref), '[]'::jsonb) FROM pg_temp.fs_comp_rows r WHERE r.kind = 'account' AND r.ref IS NOT NULL),
                                      'restatementIds', (SELECT coalesce(jsonb_agg(DISTINCT r.ref ORDER BY r.ref), '[]'::jsonb) FROM pg_temp.fs_comp_rows r WHERE r.kind = 'restatement')),
    'lines', v_lines,
    'totals', coalesce(v_totals, '{}'::jsonb),
    'accountsNotPresented', v_accounts,
    'blockers', to_jsonb(v_blockers));
  DROP TABLE pg_temp.fs_comp_rows;
  RETURN jsonb_build_object('state', 'composed') || v_body
    || jsonb_build_object('compositionSha256', encode(sha256(convert_to(v_body::text, 'UTF8')), 'hex'));
END;
$$;

-- ── 4. Every save refuses before any work ──────────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.fs_commit_revision(
  p_company_id UUID, p_report_id TEXT, p_expected_report_version INTEGER, p_idempotency_key TEXT,
  p_period_year INTEGER, p_provenance_origin TEXT, p_report_document JSONB, p_content_hash TEXT,
  p_evidence JSONB, p_evidence_batch_ids TEXT[], p_evaluation JSONB
)
  RETURNS public.financial_statement_reports
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = pg_catalog, public
AS $$
DECLARE
  v_actor    UUID;
  v_version  INTEGER;
  v_doc_hash TEXT;
  v_hash     TEXT;
  v_group    public.financial_statement_correction_groups;
  v_latest   public.financial_statement_reports;
  v_row      public.financial_statement_reports;
  v_eb       JSONB;
  v_stored   public.financial_evidence_batches;
  v_ids      TEXT[] := coalesce(p_evidence_batch_ids, '{}');
BEGIN
  v_actor := public.fs_actor_member_id(p_company_id);
  -- [20261115100000] Account capacity is refused before any validation, hashing or write (fs_account_capacity).
  DECLARE
    v_cap jsonb := public.fs_account_capacity(p_company_id, p_period_year);
  BEGIN
    IF v_cap ->> 'state' = 'measured' AND NOT (v_cap ->> 'within')::boolean THEN
      RAISE EXCEPTION 'ACCOUNT_CAPACITY_EXCEEDED: the statements would read % certified accounts across the current and comparative trial balances; this release supports %. Nothing was stored; saved versions and issued packs stay available',
        v_cap ->> 'total', v_cap ->> 'bound' USING ERRCODE = '22023';
    END IF;
  END;

  IF p_expected_report_version IS NULL OR p_expected_report_version < 0
     OR p_idempotency_key IS NULL OR length(p_idempotency_key) NOT BETWEEN 8 AND 200
     OR p_content_hash !~ '^[0-9a-f]{64}$'
     OR jsonb_typeof(p_evaluation) IS DISTINCT FROM 'object'
     OR jsonb_typeof(coalesce(p_evidence, '[]'::jsonb)) IS DISTINCT FROM 'array'
     OR jsonb_array_length(coalesce(p_evidence, '[]'::jsonb)) > 64 THEN
    RAISE EXCEPTION 'INVALID: a revision needs a non-negative expected version, an idempotency key, a content hash, an evaluation and at most 64 evidence batches' USING ERRCODE = '22023';
  END IF;
  v_version := p_expected_report_version + 1;
  PERFORM public.fs_assert_report_document(p_report_document, p_report_id, v_version, p_company_id);

  -- Every evidence batch this call ingests must be referenced by the version it creates: no orphan evidence.
  FOR v_eb IN SELECT * FROM jsonb_array_elements(coalesce(p_evidence, '[]'::jsonb)) LOOP
    IF NOT ((v_eb ->> 'evidenceBatchId') = ANY (v_ids)) OR (v_eb ->> 'evidenceBatchId') IS NULL THEN
      RAISE EXCEPTION 'INVALID: evidence batch % is ingested by this revision but not referenced by the report version it creates', v_eb ->> 'evidenceBatchId' USING ERRCODE = '22023';
    END IF;
  END LOOP;

  -- [20261115100000] Evidence aggregate PREFLIGHT (fs_work_bounds().evidenceRowsPerVersion): the rows the version WOULD
  -- reference - every incoming batch document's rows plus the rows of each referenced batch already stored - are counted
  -- here, BEFORE the idempotency read, the lineage lock, any ingestion, hashing or write. The BEFORE INSERT trigger on the
  -- version row (20261114100000) stays as the last defence against a bypass or a race; this is the refusal a caller sees.
  DECLARE
    v_rows_in   bigint := 0;
    v_rows_kept bigint := 0;
    v_row_bound bigint := (public.fs_work_bounds() ->> 'evidenceRowsPerVersion')::bigint;
    v_incoming  text[] := ARRAY(SELECT e ->> 'evidenceBatchId' FROM jsonb_array_elements(coalesce(p_evidence, '[]'::jsonb)) e);
  BEGIN
    SELECT coalesce(sum(CASE WHEN jsonb_typeof(e -> 'batchDocument' -> 'rows') = 'array' THEN jsonb_array_length(e -> 'batchDocument' -> 'rows') ELSE 0 END), 0)
      INTO v_rows_in FROM jsonb_array_elements(coalesce(p_evidence, '[]'::jsonb)) e;
    SELECT coalesce(sum(jsonb_array_length(b.batch_document -> 'rows')), 0) INTO v_rows_kept
      FROM public.financial_evidence_batches b
     WHERE b.evidence_batch_id = ANY (v_ids) AND NOT (b.evidence_batch_id = ANY (v_incoming)) AND b.company_id = p_company_id
       AND jsonb_typeof(b.batch_document -> 'rows') = 'array';
    IF v_rows_in + v_rows_kept > v_row_bound THEN
      RAISE EXCEPTION 'EVIDENCE_ROWS_PER_VERSION_LIMIT: the version would reference % evidence rows (% incoming, % already stored); at most % rows of evidence may stand behind one version. Nothing was stored.',
        v_rows_in + v_rows_kept, v_rows_in, v_rows_kept, v_row_bound USING ERRCODE = '22023';
    END IF;
  END;
  v_doc_hash := public.fs_sha256_hex(p_report_document::text);
  v_hash := public.fs_sha256_hex(concat_ws('|', p_expected_report_version::text, coalesce(p_evidence, '[]'::jsonb)::text, v_doc_hash, p_content_hash, array_to_string(v_ids, ','), p_evaluation::text, p_period_year::text, p_provenance_origin));

  PERFORM pg_advisory_xact_lock(hashtext('financial_statement_reports:' || p_report_id));

  SELECT * INTO v_group FROM public.financial_statement_correction_groups WHERE company_id = p_company_id AND idempotency_key = p_idempotency_key;
  IF FOUND THEN
    IF v_group.group_hash = v_hash AND v_group.report_id = p_report_id THEN
      SELECT * INTO v_row FROM public.financial_statement_reports WHERE report_id = p_report_id AND report_version = v_group.to_report_version;
      RETURN v_row;
    END IF;
    RAISE EXCEPTION 'REPLAY_CONFLICT: idempotency key already used with a different revision' USING ERRCODE = 'PT409';
  END IF;

  SELECT * INTO v_latest FROM public.financial_statement_reports WHERE report_id = p_report_id ORDER BY report_version DESC LIMIT 1;
  IF FOUND THEN
    IF v_latest.company_id <> p_company_id THEN
      RAISE EXCEPTION 'FORBIDDEN: report lineage % is not accessible to this company', p_report_id USING ERRCODE = '42501';
    END IF;
    -- An equivalent revision (same content, same evidence) already landed at this very version: converge on it.
    IF v_latest.report_version = v_version AND v_latest.document_hash = v_doc_hash AND v_latest.evidence_batch_ids = v_ids THEN
      RETURN v_latest;
    END IF;
    -- Nothing changed relative to the current version (version number aside): reuse it, write nothing.
    IF v_latest.report_version = p_expected_report_version
       AND (v_latest.report_document #- '{reportIdentity,reportVersion}') = (p_report_document #- '{reportIdentity,reportVersion}')
       AND v_latest.evidence_batch_ids = v_ids THEN
      RETURN v_latest;
    END IF;
    IF v_latest.period_year <> p_period_year OR v_latest.provenance_origin <> p_provenance_origin THEN
      RAISE EXCEPTION 'STALE_REPORT_VERSION: report % cannot change its period or provenance origin', p_report_id USING ERRCODE = 'PT409';
    END IF;
  END IF;
  IF coalesce(v_latest.report_version, 0) <> p_expected_report_version THEN
    RAISE EXCEPTION 'STALE_REPORT_VERSION: the report is at version % but the revision was formed against %', coalesce(v_latest.report_version, 0), p_expected_report_version USING ERRCODE = 'PT409';
  END IF;

  -- From here on every statement is one transaction: any error rolls all of it back.
  FOR v_eb IN SELECT * FROM jsonb_array_elements(coalesce(p_evidence, '[]'::jsonb)) LOOP
    v_stored := public.fs_ingest_evidence_internal(
      v_actor, v_eb ->> 'evidenceBatchId', p_company_id, v_eb ->> 'reportingPeriodId', v_eb ->> 'evidenceType', v_eb ->> 'periodRole',
      v_eb ->> 'seriesKey', v_eb ->> 'schemaVersion', v_eb ->> 'sourceFileName', v_eb ->> 'contentHash', v_eb ->> 'currency',
      (v_eb ->> 'scale')::INTEGER, v_eb -> 'batchDocument', v_eb ->> 'validationStatus', v_eb -> 'diagnostics', v_eb ->> 'expectedPreviousBatchId');
    -- An exact replay of already-stored source content returns the stored batch: the version references THAT batch.
    IF v_stored.evidence_batch_id <> (v_eb ->> 'evidenceBatchId') THEN
      v_ids := array_replace(v_ids, v_eb ->> 'evidenceBatchId', v_stored.evidence_batch_id);
    END IF;
  END LOOP;
  IF EXISTS (SELECT 1 FROM unnest(v_ids) AS e(id) WHERE NOT EXISTS (SELECT 1 FROM public.financial_evidence_batches b WHERE b.evidence_batch_id = e.id AND b.company_id = p_company_id)) THEN
    RAISE EXCEPTION 'NOT_FOUND: a referenced evidence batch does not exist for this company' USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO public.financial_statement_reports (
    report_id, report_version, company_id, period_year, provenance_origin, report_document, content_hash, document_hash,
    evidence_batch_ids, created_by_firm_member_id
  ) VALUES (
    p_report_id, v_version, p_company_id, p_period_year, p_provenance_origin, p_report_document, p_content_hash, v_doc_hash, v_ids, v_actor
  ) RETURNING * INTO v_row;

  PERFORM public.fs_store_evaluation(
    p_evaluation ->> 'evaluationRunId', p_report_id, v_version, p_company_id,
    p_evaluation ->> 'rulePackId', p_evaluation ->> 'rulePackVersion', p_evaluation ->> 'engineVersion',
    p_evaluation ->> 'inputHash', p_evaluation -> 'findings');

  INSERT INTO public.financial_statement_correction_groups (
    group_id, idempotency_key, company_id, report_id, expected_report_version, from_report_version, to_report_version,
    step_count, group_hash, applied_by_firm_member_id
  ) VALUES (
    'rev-' || left(v_hash, 32), p_idempotency_key, p_company_id, p_report_id, p_expected_report_version, v_version, v_version, 1, v_hash, v_actor
  );

  PERFORM public.fs_audit_event(p_company_id, p_report_id, 'REVISION_COMMITTED',
    jsonb_build_object('reportVersion', v_version::text, 'contentHash', p_content_hash, 'evidenceBatchIds', to_jsonb(v_ids),
                       'ingested', jsonb_array_length(coalesce(p_evidence, '[]'::jsonb))::text, 'evaluationRunId', p_evaluation ->> 'evaluationRunId', 'revisionHash', v_hash), v_actor);
  RETURN v_row;
END;
$$;

-- ── 4b. The comparative approval answers by name ───────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.fs_approve_comparatives(p_company_id uuid, p_period_year integer, p_approve boolean, p_reason text, p_request_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_status jsonb;
  v_prior record;
  v_latest record;
  v_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'UNAUTHENTICATED' USING ERRCODE = '28000'; END IF;
  IF p_company_id IS NULL OR p_period_year IS NULL OR p_approve IS NULL OR p_request_id IS NULL OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 3 AND 2000 THEN
    RETURN jsonb_build_object('outcome', 'invalid_request');
  END IF;
  IF NOT public.workspace_capability_allowed(p_company_id, v_uid, 'review_close') THEN RETURN jsonb_build_object('outcome', 'forbidden'); END IF;
  IF NOT public.fs_rollout_allows(p_company_id) THEN RETURN jsonb_build_object('outcome', 'feature_disabled'); END IF;
  IF (SELECT c.reporting_framework FROM public.companies c WHERE c.id = p_company_id) IS DISTINCT FROM 'ifrs_for_smes' THEN
    RETURN jsonb_build_object('outcome', 'framework_not_ifrs_for_smes');
  END IF;
  -- [20261115100000] Account capacity: the approval answers by name BEFORE the lock, the status (a composition) or any
  -- write; without it the approval row's check constraint (no comparative sha at over_capacity) surfaces as a raw error.
  DECLARE
    v_cap jsonb := public.fs_account_capacity(p_company_id, p_period_year);
  BEGIN
    IF v_cap ->> 'state' = 'measured' AND NOT (v_cap ->> 'within')::boolean THEN
      RETURN jsonb_build_object('outcome', 'over_capacity', 'capacity', v_cap);
    END IF;
  END;
  PERFORM pg_advisory_xact_lock(hashtextextended('fs_comparatives:' || p_company_id::text || ':' || p_period_year::text, 0));
  SELECT * INTO v_prior FROM public.fs_comparative_approvals a WHERE a.actor_user_id = v_uid AND a.request_id = p_request_id;
  IF FOUND THEN
    IF v_prior.company_id = p_company_id AND v_prior.period_year = p_period_year AND (v_prior.action = 'approved') = p_approve THEN
      RETURN jsonb_build_object('outcome', 'recorded', 'replay', true, 'approvalId', v_prior.id);
    END IF;
    RETURN jsonb_build_object('outcome', 'request_reused');
  END IF;
  v_status := public.fs_comparatives_status(p_company_id, p_period_year) -> 'comparative';
  SELECT a.action INTO v_latest FROM public.fs_comparative_approvals a WHERE a.company_id = p_company_id AND a.period_year = p_period_year ORDER BY a.seq DESC LIMIT 1;
  IF p_approve THEN
    IF v_status ->> 'state' = 'approved' THEN RETURN jsonb_build_object('outcome', 'unchanged'); END IF;
    IF v_status ->> 'state' NOT IN ('unapproved', 'approval_stale') THEN RETURN jsonb_build_object('outcome', 'not_approvable', 'state', coalesce(v_status ->> 'state', 'unavailable')); END IF;
  ELSE
    IF v_latest.action IS DISTINCT FROM 'approved' THEN RETURN jsonb_build_object('outcome', 'unchanged'); END IF;
  END IF;
  INSERT INTO public.fs_comparative_approvals (company_id, period_year, action, comparative_sha256, reason, actor_user_id, firm_member_id, request_id)
  VALUES (p_company_id, p_period_year, CASE WHEN p_approve THEN 'approved' ELSE 'withdrawn' END, CASE WHEN p_approve THEN v_status ->> 'comparativeSha256' END,
          btrim(p_reason), v_uid, public._cr_member(p_company_id, v_uid), p_request_id)
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('outcome', 'recorded', 'approvalId', v_id, 'comparativeSha256', CASE WHEN p_approve THEN v_status ->> 'comparativeSha256' END);
END;
$$;

-- ── 5. Readiness, REVIEWED/FINAL and the binding trigger refuse by name ────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.fs_publication_blockers(p_company_id UUID, p_report_id TEXT, p_version INTEGER)
  RETURNS TEXT[]
  LANGUAGE plpgsql
  VOLATILE
  SET search_path = pg_catalog, public
AS $$
DECLARE
  v_report   public.financial_statement_reports;
  v_req      public.financial_statement_framework_requirements;
  v_b        public.financial_evidence_batches;
  v_out      TEXT[] := '{}';
  v_doc      JSONB;
  v_type     TEXT;
  v_cid      TEXT;
  v_id       TEXT;
  v_latest   INTEGER;
  v_n        INTEGER;
  v_comp_any BOOLEAN;
  v_txt      TEXT;
  v_cov      TEXT;
  v_rec      JSONB;
  v_disc     JSONB;
  v_has_budget BOOLEAN;
  v_input    JSONB;
  v_hashes   TEXT[];
  v_deps     JSONB;
  v_bad      TEXT[];
BEGIN
  SELECT * INTO v_report FROM public.financial_statement_reports r
   WHERE r.report_id = p_report_id AND r.report_version = p_version AND r.company_id = p_company_id;
  IF NOT FOUND THEN
    RETURN ARRAY['REPORT_VERSION_NOT_FOUND'];
  END IF;
  v_doc := v_report.report_document;

  SELECT max(r.report_version) INTO v_latest FROM public.financial_statement_reports r WHERE r.report_id = p_report_id;
  IF v_latest <> p_version THEN v_out := array_append(v_out, 'NOT_LATEST_VERSION'); END IF;
  -- [20261115100000] Account capacity: named and returned at once, before any recomposition or evidence work.
  DECLARE
    v_cap jsonb := public.fs_account_capacity(p_company_id, v_report.period_year);
  BEGIN
    IF v_cap ->> 'state' = 'measured' AND NOT (v_cap ->> 'within')::boolean THEN
      RETURN array_append(v_out, 'ACCOUNT_CAPACITY_EXCEEDED:' || (v_cap ->> 'total') || '/' || (v_cap ->> 'bound'));
    END IF;
  END;

  -- [20261111100000] The one supported publication path: an IFRS for SMEs report derived from the authoritative trial
  -- balance. Every other framework or provenance is refused by name. The generic checks below still report what else is
  -- missing, but no such report can ever reach REVIEWED or FINAL through them (and fs_bind_publication refuses it too).
  IF v_report.provenance_origin IS DISTINCT FROM 'TRIAL_BALANCE_DERIVED' OR v_doc #>> '{framework,kind}' IS DISTINCT FROM 'IFRS_FOR_SMES' THEN
    v_out := v_out || ('PUBLICATION_PATH_UNSUPPORTED:' || coalesce(v_doc #>> '{framework,kind}', 'FRAMEWORK_UNKNOWN') || ':' || coalesce(v_report.provenance_origin, 'PROVENANCE_UNKNOWN'));
  END IF;

  SELECT * INTO v_req FROM public.financial_statement_framework_requirements f WHERE f.framework_kind = v_doc #>> '{framework,kind}';
  IF NOT FOUND THEN
    v_out := array_append(v_out, 'FRAMEWORK_UNKNOWN');
  ELSE
    v_comp_any := jsonb_array_length(coalesce(v_doc -> 'comparativePeriods', '[]'::jsonb)) > 0;
    -- [20261017100000] The first-period exception: an approved first-period declaration (approve_certification, evidence
    -- dated within the period) satisfies the comparative requirement; nothing else does (reference-only figures never do).
    IF v_req.comparatives_required AND NOT v_comp_any AND NOT public.fs_first_period_declared(p_company_id, v_report.period_year) THEN
      v_out := array_append(v_out, 'COMPARATIVE_PERIOD_MISSING');
    END IF;

    FOREACH v_type IN ARRAY v_req.required_statement_types LOOP
      IF NOT jsonb_path_exists(v_doc, '$.statements[*] ? (@.type == $t)', jsonb_build_object('t', v_type)) THEN
        v_out := v_out || ('MISSING_STATEMENT:' || v_type);
      ELSIF v_req.comparatives_required AND v_comp_any THEN
        FOR v_cid IN SELECT jsonb_array_elements(v_doc -> 'comparativePeriods') ->> 'periodId' LOOP
          IF NOT jsonb_path_exists(v_doc, '$.statements[*] ? (@.type == $t).sections[*].lines[*].factBindings[*] ? (@.periodId == $c)',
                                   jsonb_build_object('t', v_type, 'c', v_cid)) THEN
            v_out := v_out || ('COMPARATIVE_FIGURES_MISSING:' || v_type || ':' || v_cid);
          END IF;
        END LOOP;
      END IF;
    END LOOP;

    FOREACH v_type IN ARRAY v_req.required_evidence_types LOOP
      IF NOT EXISTS (
        SELECT 1 FROM public.financial_evidence_batches b
         WHERE b.company_id = p_company_id AND b.evidence_batch_id = ANY (v_report.evidence_batch_ids) AND b.evidence_type = v_type
      ) THEN
        v_out := v_out || ('REQUIRED_EVIDENCE_MISSING:' || v_type);
      END IF;
    END LOOP;
  END IF;

  FOREACH v_id IN ARRAY v_report.evidence_batch_ids LOOP
    SELECT * INTO v_b FROM public.financial_evidence_batches b WHERE b.evidence_batch_id = v_id AND b.company_id = p_company_id;
    IF NOT FOUND THEN
      v_out := v_out || ('EVIDENCE_MISSING:' || v_id);
    ELSE
      IF v_b.validation_status NOT IN ('VALID', 'VALID_WITH_WARNINGS') THEN v_out := v_out || ('EVIDENCE_NOT_VALID:' || v_id); END IF;
      IF EXISTS (SELECT 1 FROM public.financial_evidence_batches n
                  WHERE n.company_id = v_b.company_id AND n.reporting_period_id = v_b.reporting_period_id AND n.evidence_type = v_b.evidence_type
                    AND n.period_role = v_b.period_role AND n.series_key = v_b.series_key AND n.version > v_b.version) THEN
        v_out := v_out || ('EVIDENCE_SUPERSEDED:' || v_id);
      END IF;
    END IF;
  END LOOP;

  IF v_req.framework_kind IS NOT NULL THEN
    -- Cash-flow authority: a ledger-derived closing figure AND proof that the ledger is complete account by account.
    IF 'STATEMENT_OF_CASH_FLOWS' = ANY (v_req.required_statement_types) THEN
      IF NOT jsonb_path_exists(v_doc, '$.statements[*] ? (@.type == "STATEMENT_OF_CASH_FLOWS").sections[*].lines[*] ? (@.lineId == "line:cf:closing")') THEN
        v_out := array_append(v_out, 'CASHFLOW_CLOSING_CASH_MISSING');
      END IF;
      IF NOT jsonb_path_exists(v_doc, '$.notes[*] ? (@.noteId == "note:cash-ledger-authority")') THEN
        v_out := array_append(v_out, 'CASHFLOW_LEDGER_AUTHORITY_MISSING');
      ELSIF NOT jsonb_path_exists(v_doc, '$.notes[*] ? (@.noteId == "note:cash-ledger-authority").monetaryFactIds[*] ? (@ starts with "fact:cashroll:ledger:")') THEN
        v_out := array_append(v_out, 'CASHFLOW_LEDGER_AUTHORITY_UNRESOLVED');
      END IF;
    END IF;

    -- Reviewed mappings: the trial balance must have been prepared with every account reviewed and unambiguous.
    IF v_req.requires_mapping_review THEN
      SELECT d ->> 'text' INTO v_cov FROM jsonb_array_elements(coalesce(v_doc -> 'textualDisclosures', '[]'::jsonb)) d WHERE d ->> 'disclosureId' = 'mapping:coverage' LIMIT 1;
      IF v_cov IS NULL THEN
        v_out := array_append(v_out, 'MAPPING_REVIEW_UNRECORDED');
      ELSIF v_cov !~ '^total=[1-9][0-9]*;unmapped=0;ambiguous=0$' THEN
        v_out := v_out || ('MAPPING_UNREVIEWED:' || left(v_cov, 60));
      END IF;
    END IF;

    -- Disclosure checklist: every framework disclosure area present and not MISSING.
    FOREACH v_id IN ARRAY v_req.disclosure_area_ids LOOP
      SELECT d ->> 'text' INTO v_txt FROM jsonb_array_elements(coalesce(v_doc -> 'textualDisclosures', '[]'::jsonb)) d WHERE d ->> 'disclosureId' = 'checklist:' || v_id LIMIT 1;
      IF v_txt IS NULL THEN
        v_out := v_out || ('DISCLOSURE_CHECKLIST_ABSENT:' || v_id);
      ELSIF v_txt LIKE 'MISSING:%' THEN
        v_out := v_out || ('DISCLOSURE_CHECKLIST_INCOMPLETE:' || v_id);
      END IF;
    END LOOP;

    -- Budget completeness, wherever a budget is part of this report.
    v_has_budget := EXISTS (SELECT 1 FROM public.financial_evidence_batches b WHERE b.company_id = p_company_id AND b.evidence_batch_id = ANY (v_report.evidence_batch_ids) AND b.evidence_type = 'BUDGET');
    IF jsonb_path_exists(v_doc, '$.textualDisclosures[*] ? (@.disclosureId == "budget:gap")') THEN
      v_out := array_append(v_out, 'BUDGET_COMPARISON_GAP');
    ELSIF v_has_budget AND NOT jsonb_path_exists(v_doc, '$.textualDisclosures[*] ? (@.disclosureId starts with "budget:line:")') THEN
      v_out := array_append(v_out, 'BUDGET_COMPARISON_MISSING');
    END IF;
    FOR v_disc IN SELECT d FROM jsonb_array_elements(coalesce(v_doc -> 'textualDisclosures', '[]'::jsonb)) d WHERE d ->> 'disclosureId' LIKE 'budget:line:%' ORDER BY d ->> 'disclosureId' LOOP
      v_rec := public.fs_try_jsonb(v_disc ->> 'text');
      IF v_rec IS NULL OR jsonb_typeof(v_rec) <> 'object' THEN
        v_out := v_out || ('BUDGET_LINE_UNREADABLE:' || (v_disc ->> 'disclosureId'));
      ELSE
        IF coalesce(v_rec ->> 'matched', 'false') <> 'true' THEN v_out := v_out || ('BUDGET_LINE_UNMATCHED:' || coalesce(v_rec ->> 'lineKey', '?')); END IF;
        IF v_rec ->> 'required' = 'true' AND coalesce(btrim(v_rec ->> 'explanation'), '') = '' THEN v_out := v_out || ('BUDGET_EXPLANATION_MISSING:' || coalesce(v_rec ->> 'lineKey', '?')); END IF;
      END IF;
    END LOOP;
  END IF;

  -- [20261017100000] A trial-balance report is final only on the CURRENT authoritative reporting input and a finished Close
  -- Review: its trial-balance facts must all come from one input identity equal to fs_reporting_input's now (else stale);
  -- the findings of that authority must have been checked with no unresolved blocking finding; no adjustment may be
  -- awaiting a decision, and no approved adjustment may be awaiting a revalidation decision after a re-check.
  IF v_report.provenance_origin = 'TRIAL_BALANCE_DERIVED' THEN
    v_input := public.fs_reporting_input(p_company_id, v_report.period_year);
    SELECT array_agg(DISTINCT s) INTO v_hashes
      FROM jsonb_path_query(v_doc, '$.facts[*].provenance.source ? (@.artifactKind == "TRIAL_BALANCE").sourceHash') h(s0), LATERAL (SELECT h.s0 #>> '{}' AS s) x;
    IF v_input ->> 'state' IS DISTINCT FROM 'current' THEN
      v_out := v_out || ('REPORTING_INPUT_NOT_AUTHORITATIVE:' || coalesce(v_input ->> 'state', 'unknown'));
    ELSIF v_hashes IS NULL OR array_length(v_hashes, 1) <> 1 OR v_hashes[1] IS DISTINCT FROM v_input ->> 'inputSha256' THEN
      v_out := array_append(v_out, 'REPORTING_INPUT_STALE');
    END IF;
    IF v_input ->> 'state' = 'current' THEN
      IF v_input #>> '{findings,state}' IS DISTINCT FROM 'current' THEN
        v_out := array_append(v_out, 'CLOSE_REVIEW_FINDINGS_NOT_CHECKED');
      ELSIF coalesce((v_input #>> '{findings,unresolvedBlocking}')::integer, 0) > 0 THEN
        v_out := v_out || ('CLOSE_REVIEW_BLOCKING_FINDINGS:' || (v_input #>> '{findings,unresolvedBlocking}'));
      END IF;
      SELECT count(*) INTO v_n FROM public.close_review_adjustments a
       WHERE a.company_id = p_company_id AND a.period_year = v_report.period_year
         AND a.certification_id = (v_input #>> '{current,certificationId}')::uuid AND public._cr_adjustment_status(a.id) = 'proposed';
      IF v_n > 0 THEN v_out := v_out || ('CLOSE_REVIEW_ADJUSTMENTS_UNDECIDED:' || v_n); END IF;
      IF coalesce((v_input ->> 'adjustmentsRequiringRevalidation')::integer, 0) > 0 THEN
        v_out := v_out || ('CLOSE_REVIEW_ADJUSTMENTS_REQUIRE_REVALIDATION:' || (v_input ->> 'adjustmentsRequiringRevalidation'));
      END IF;
    END IF;
  END IF;

  -- [20261021100000, 20261111100000] An IFRS for SMEs trial-balance report is bound to its reporting dependencies — the
  -- database's composition, notes status, comparative status and evidence statements — and its four statements must carry
  -- EXACTLY the database's figures under their fixed fact identities; nothing else may be bound there. Every blocker of
  -- those dependencies is a blocker of the report; any later change makes the binding stale.
  IF v_report.provenance_origin = 'TRIAL_BALANCE_DERIVED' AND v_doc #>> '{framework,kind}' = 'IFRS_FOR_SMES' THEN
    v_deps := public.fs_reporting_dependencies(p_company_id, v_report.period_year);
    IF v_deps ->> 'state' IS DISTINCT FROM 'current' THEN
      v_out := v_out || ('REPORTING_DEPENDENCIES_UNAVAILABLE:' || coalesce(v_deps ->> 'state', 'unknown'));
    ELSE
      IF v_doc #>> '{reportingDependencies,dependenciesSha256}' IS NULL THEN
        v_out := array_append(v_out, 'REPORTING_DEPENDENCIES_UNBOUND');
      ELSIF v_doc #>> '{reportingDependencies,dependenciesSha256}' IS DISTINCT FROM v_deps ->> 'dependenciesSha256' THEN
        v_out := array_append(v_out, 'REPORTING_DEPENDENCIES_STALE');
      END IF;
      -- [20261111100000] The edition the document seals must be the one the server resolves for the period.
      IF v_doc #>> '{framework,version}' IS NULL THEN
        v_out := array_append(v_out, 'FRAMEWORK_EDITION_UNRECORDED');
      ELSIF v_doc #>> '{framework,version}' IS DISTINCT FROM v_deps ->> 'packId' THEN
        v_out := v_out || ('FRAMEWORK_EDITION_MISMATCH:' || (v_doc #>> '{framework,version}') || ':' || (v_deps ->> 'packId'));
      END IF;
      -- [20261111100000] Only the 2015 edition's requirement texts are verified; a report composed under the third edition
      -- (a period beginning on or after 2027-01-01, or an early-application election) is refused by name.
      IF v_deps ->> 'packId' IS DISTINCT FROM 'ifrs-for-smes/2015' THEN
        v_out := v_out || ('FRAMEWORK_EDITION_UNSUPPORTED:' || coalesce(v_deps ->> 'packId', 'unknown'));
      END IF;
      v_out := v_out || ARRAY(SELECT jsonb_array_elements_text(v_deps -> 'blockers'));
      -- [20261111100000] Every evidence batch a server figure rests on is bound to this version.
      FOR v_rec IN SELECT b FROM jsonb_array_elements(coalesce(v_deps -> 'evidenceBatches', '[]'::jsonb)) b LOOP
        IF NOT ((v_rec ->> 'batchId') = ANY (v_report.evidence_batch_ids)) THEN
          v_out := v_out || ('EVIDENCE_NOT_BOUND:' || (v_rec ->> 'type') || ':' || (v_rec ->> 'role'));
        END IF;
      END LOOP;
      -- Every composed figure present with exactly its amount ...
      SELECT array_agg(f ->> 'factId' ORDER BY f ->> 'factId') INTO v_bad
        FROM jsonb_array_elements(v_deps -> 'figures') f
       WHERE NOT jsonb_path_exists(v_doc, '$.facts[*] ? (@.factId == $id && @.value.minorUnits.__bigint__ == $m)',
                                   jsonb_build_object('id', f ->> 'factId', 'm', f ->> 'amountMinor'));
      IF v_bad IS NOT NULL THEN v_out := v_out || ('STATEMENT_FIGURE_MISMATCH:' || array_length(v_bad, 1) || ':' || v_bad[1]); END IF;
      -- ... and nothing else bound on the four statements (20261111100000: the statements of changes in equity and cash flows too).
      SELECT array_agg(DISTINCT b ORDER BY b) INTO v_bad
        FROM jsonb_path_query(v_doc, '$.statements[*] ? (@.type == "STATEMENT_OF_FINANCIAL_POSITION" || @.type == "STATEMENT_OF_PROFIT_OR_LOSS" || @.type == "STATEMENT_OF_CHANGES_IN_EQUITY" || @.type == "STATEMENT_OF_CASH_FLOWS").sections[*].lines[*].factBindings[*].factId') q(j),
             LATERAL (SELECT q.j #>> '{}' AS b) x
       WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_deps -> 'figures') f WHERE f ->> 'factId' = x.b);
      IF v_bad IS NOT NULL THEN v_out := v_out || ('STATEMENT_FIGURE_NOT_COMPOSED:' || array_length(v_bad, 1) || ':' || v_bad[1]); END IF;
    END IF;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.financial_statement_evaluations e WHERE e.report_id = p_report_id AND e.report_version = p_version) THEN
    v_out := array_append(v_out, 'NOT_EVALUATED');
  ELSE
    v_n := public.fs_unresolved_blocking_count(p_report_id, p_version);
    IF v_n > 0 THEN v_out := v_out || ('BLOCKING_FINDINGS:' || v_n); END IF;
    v_n := public.fs_unmet_reconciliation_count(p_report_id, p_version);
    IF v_n > 0 THEN v_out := v_out || ('RECONCILIATION_UNMET:' || v_n); END IF;
  END IF;
  -- [20261112100000] A reviewer's BLOCKING comment on this lineage that is not resolved for THIS version's content blocks
  -- it by name; an advisory comment never does; a resolved comment whose item is unchanged stays resolved.
  v_out := v_out || ARRAY(SELECT 'REVIEW_COMMENT_UNRESOLVED:' || c.id::text
                            FROM public.fs_review_comment_states(p_company_id, p_report_id, p_version) c
                           WHERE c.severity = 'blocking' AND c.state <> 'resolved' ORDER BY c.seq);
  RETURN v_out;
END;
$$;

DO $postcondition$
BEGIN
  IF (public.fs_work_bounds() ->> 'contract') IS DISTINCT FROM 'fs-work-bounds/2'
     OR (public.fs_work_bounds() ->> 'accountsReadPerComposition')::integer <> 1000
     OR to_regprocedure('public.fs_account_capacity(uuid, integer)') IS NULL
     OR position('over_capacity' IN pg_get_functiondef('public.fs_statement_composition(uuid, integer)'::regprocedure)) = 0
     OR position('ACCOUNT_CAPACITY_EXCEEDED' IN pg_get_functiondef('public.fs_commit_revision(uuid, text, integer, text, integer, text, jsonb, text, jsonb, text[], jsonb)'::regprocedure)) = 0
     OR position('ACCOUNT_CAPACITY_EXCEEDED' IN pg_get_functiondef('public.fs_publication_blockers(uuid, text, integer)'::regprocedure)) = 0
     OR position('over_capacity' IN pg_get_functiondef('public.fs_approve_comparatives(uuid, integer, boolean, text, uuid)'::regprocedure)) = 0
     OR position('EVIDENCE_ROWS_PER_VERSION_LIMIT' IN pg_get_functiondef('public.fs_commit_revision(uuid, text, integer, text, integer, text, jsonb, text, jsonb, text[], jsonb)'::regprocedure)) = 0
     OR position('REVIEW_COMMENT_UNRESOLVED' IN pg_get_functiondef('public.fs_publication_blockers(uuid, text, integer)'::regprocedure)) = 0
     OR has_function_privilege('anon', 'public.fs_account_capacity(uuid, integer)', 'EXECUTE')
     OR NOT has_function_privilege('authenticated', 'public.fs_account_capacity(uuid, integer)', 'EXECUTE')
     OR has_function_privilege('authenticated', 'public.fs_publication_blockers(uuid, text, integer)', 'EXECUTE') THEN
    RAISE EXCEPTION 'POSTCONDITION_FAILED: the account capacity is not in its reviewed state' USING ERRCODE = 'P0001';
  END IF;
END;
$postcondition$;
$cfoclose_payload_408e84e112022264$;
  v_bytes   integer;
  v_sha256  text;
BEGIN
  v_bytes  := octet_length(convert_to(c_payload, 'UTF8'));
  v_sha256 := encode(sha256(convert_to(c_payload, 'UTF8')), 'hex');
  IF v_bytes IS DISTINCT FROM c_bytes OR v_sha256 IS DISTINCT FROM c_sha256 THEN
    RAISE EXCEPTION 'RELEASE_PAYLOAD_MISMATCH: % encloses % bytes with SHA-256 %, expected % bytes with SHA-256 %; nothing was changed',
      c_source, v_bytes, v_sha256, c_bytes, c_sha256 USING ERRCODE = '55000';
  END IF;
  EXECUTE c_payload;
END
$cfoclose_release_408e84e112022264$;
